/**
 * Diagram typefaces and deterministic text measurement.
 *
 * Diagram text uses four bundled faces (SIL Open Font License, see `src/assets/fonts`). Their
 * advance widths are stored in `font-metrics.json`, generated by `scripts/font-metrics.mjs` from
 * the same files. Wrapping and sizing read that table, never the DOM, so the compiler, the browser
 * and the CLI break every label at the same place.
 */
import metrics from './font-metrics.json';

export type FontRole = 'sans' | 'serif' | 'mono';
export const FONT_ROLES: FontRole[] = ['sans', 'serif', 'mono'];

export interface FontFace {
  /** Registered family name; unique so an installed copy of the font is never used instead. */
  family: string;
  weight: number;
  file: string;
}

export { FACES } from './font-faces';
import { FACES } from './font-faces';

export type FaceId = keyof typeof FACES;

const FALLBACK: Record<FontRole, string> = {
  sans: 'Inter, Arial, sans-serif',
  serif: "'Source Serif 4', Georgia, serif",
  mono: "'JetBrains Mono', Menlo, Consolas, monospace",
};

/** Face used for each role: titles are a little heavier than annotations in sans-serif. */
export const faceFor = (role: FontRole, title: boolean): FaceId =>
  role === 'serif' ? 'serif-600' : role === 'mono' ? 'mono-500' : title ? 'sans-600' : 'sans-500';

export const fontStack = (role: FontRole) => {
  const face = FACES[faceFor(role, true)];
  return `'${face.family}', ${FALLBACK[role]}`;
};

/** A text style: which face, at what size and line height. */
export interface TypeProfile {
  role: FontRole;
  face: FaceId;
  family: string;
  weight: number;
  size: number;
  lineHeight: number;
}

export function typeProfile(
  role: FontRole,
  title: boolean,
  size: number,
  lineHeight: number,
): TypeProfile {
  const face = faceFor(role, title);
  return { role, face, family: fontStack(role), weight: FACES[face].weight, size, lineHeight };
}

type Table = { unitsPerEm: number; fallback: number; advances: Record<string, number> };
const TABLES = metrics as unknown as Record<FaceId, Table>;

/**
 * Width of `text` in `profile`, from the stored advance widths. Kerning is ignored, which only
 * ever overstates a width slightly, so measured text fits where this says it fits.
 */
export function measureText(text: string, profile: Pick<TypeProfile, 'face' | 'size'>) {
  const table = TABLES[profile.face];
  let units = 0;
  for (const char of text) units += table.advances[char] ?? table.fallback;
  return (units * profile.size) / table.unitsPerEm;
}

/**
 * The pieces an identifier reads in, so a long one can break where a reader would: after a
 * separator (`/`, `.`, `_`, `-`, `:`) or between a lower-case letter or digit and a capital
 * (camelCase). `annotationCommands` → `annotation`, `Commands`; `src/viz/Treemap.tsx` → `src/`,
 * `viz/`, `Treemap.tsx`. A word with none of these is one piece.
 */
export function wordPieces(word: string): string[] {
  const pieces: string[] = [];
  let pending = '';
  for (const piece of word.split(/(?<=[/._:-])(?=[^/._:-])|(?<=[a-z0-9])(?=[A-Z])/)) {
    // Punctuation alone (`*.` in `examples/*.draft`) leads into the piece after it.
    if (!/[\p{L}\p{N}]/u.test(piece)) pending += piece;
    else {
      pieces.push(pending + piece);
      pending = '';
    }
  }
  if (pending && pieces.length) pieces[pieces.length - 1] += pending;
  else if (pending) pieces.push(pending);
  // A short tail (a file extension, `md` in `notes.md`) stays with the piece before it.
  if (pieces.length > 1 && pieces[pieces.length - 1].length <= 3)
    pieces.splice(-2, 2, pieces[pieces.length - 2] + pieces[pieces.length - 1]);
  return pieces;
}

/** Width of the widest piece of any word in `text`: the narrowest line it wraps into whole. */
export function widestPiece(text: string, profile: Pick<TypeProfile, 'face' | 'size'>) {
  return Math.max(
    0,
    ...String(text)
      .split(/\s+/)
      .flatMap(wordPieces)
      .map(piece => measureText(piece, profile)),
  );
}

/**
 * A paragraph's words, with a short token kept beside its neighbour so no line starts or ends on
 * it alone: a lone symbol (`<`, `~`, `≈`) joins the word after it, and a short unit (`s`, `ms`,
 * `%`) joins the number before it. `in < 5 s` breaks as `in` / `< 5 s`, never `in < 5` / `s`. A
 * joined token that would not fit in `width` stays as separate words.
 */
function tokens(paragraph: string, width: number, profile: TypeProfile) {
  const out: string[] = [];
  let lead = '';
  for (const word of paragraph.split(/\s+/)) {
    if (!word) continue;
    const prev = out[out.length - 1];
    const unit =
      !lead &&
      prev !== undefined &&
      /\d$/.test(prev) &&
      /^(%|[\p{L}µ]{1,3}[.,;:)]?)$/u.test(word) &&
      measureText(prev + ' ' + word, profile) <= width;
    if (unit) out[out.length - 1] = prev + ' ' + word;
    else if (lead && measureText(lead + ' ' + word, profile) <= width) {
      out.push(lead + ' ' + word);
      lead = '';
    } else {
      if (lead) out.push(lead);
      lead = '';
      if (!/[\p{L}\p{N}]/u.test(word) && word.length <= 2) lead = word;
      else out.push(word);
    }
  }
  if (lead) {
    const prev = out[out.length - 1];
    if (prev !== undefined && measureText(prev + ' ' + lead, profile) <= width)
      out[out.length - 1] = prev + ' ' + lead;
    else out.push(lead);
  }
  return out;
}

/** Greedy line breaks of `words` at `width`. */
function greedy(words: string[], width: number, profile: TypeProfile): string[] {
  const fits = (s: string) => measureText(s, profile) <= width;
  const lines: string[] = [];
  let line = '';
  for (const word of words) {
    if (!fits(word)) {
      if (line) lines.push(line);
      let part = '';
      for (const piece of wordPieces(word)) {
        if (part && fits(part + piece)) {
          part += piece;
          continue;
        }
        if (part) lines.push(part);
        part = '';
        if (fits(piece)) {
          part = piece;
          continue;
        }
        for (const char of piece) {
          if (part && !fits(part + char)) {
            lines.push(part);
            part = '';
          }
          part += char;
        }
      }
      line = part;
      continue;
    }
    if (line && !fits(line + ' ' + word)) {
      lines.push(line);
      line = word;
    } else line += (line ? ' ' : '') + word;
  }
  lines.push(line);
  return lines;
}

/**
 * `words` broken into `n` lines no wider than `width` whose widths run as near equal as they can:
 * the least sum of squared distances from the mean width. Undefined when a word alone is too
 * wide, which leaves the greedy breaks.
 */
function even(words: string[], n: number, width: number, profile: TypeProfile) {
  const w = words.map(word => measureText(word, profile)),
    space = measureText(' ', profile);
  if (w.some(x => x > width)) return;
  const at = [0];
  for (const x of w) at.push(at[at.length - 1] + x);
  const span = (i: number, j: number) => at[j] - at[i] + (j - i - 1) * space,
    mean = span(0, w.length) / n,
    tie = (mean / 10) ** 2;
  // cost[k][j]: best cost of the first j words in k lines; from[k][j] where the last line starts.
  const cost = [[0, ...w.map(() => Infinity)]],
    from: number[][] = [[]];
  for (let k = 1; k <= n; k++) {
    cost.push(w.map(() => Infinity).concat(Infinity));
    from.push([]);
    for (let j = k; j <= w.length; j++)
      for (let i = j - 1; i >= k - 1 && span(i, j) <= width; i--) {
        const c = cost[k - 1][i] + (span(i, j) - mean) ** 2;
        // A near tie keeps the earlier lines longer, the shape a reader expects.
        if (c < cost[k][j] - tie) [cost[k][j], from[k][j]] = [c, i];
      }
  }
  if (!Number.isFinite(cost[n][w.length])) return;
  const out: string[] = [];
  for (let k = n, j = w.length; k > 0; j = from[k][j], k--)
    out.unshift(words.slice(from[k][j], j).join(' '));
  return out;
}

/**
 * Break text into lines no wider than `width`, starting a new line at each `\n`. A word longer
 * than a line breaks between its pieces (`wordPieces`), and only a piece that is itself too long
 * breaks by character. With `balance`, a paragraph that wraps keeps its line count but its lines
 * run near equal (`even`), so no word sits alone on the last line when a better break exists.
 */
export function wrapLines(
  text: string,
  width: number,
  profile: TypeProfile,
  balance = false,
): string[] {
  const lines: string[] = [];
  for (const paragraph of String(text).split('\n')) {
    const words = balance
      ? tokens(paragraph, width, profile)
      : paragraph.split(/\s+/).filter(Boolean);
    const best = greedy(words, width, profile);
    lines.push(
      ...(balance && best.length > 1 ? (even(words, best.length, width, profile) ?? best) : best),
    );
  }
  return lines.length ? lines : [''];
}

/** Shorten text with an ellipsis so it fits in `width`. */
export function truncateText(text: string, width: number, profile: TypeProfile) {
  if (measureText(text, profile) <= width) return text;
  let out = text;
  while (out && measureText(out + '…', profile) > width) out = out.slice(0, -1);
  return out.trimEnd() + '…';
}
